 <div class="screen hidden" id="end"><section class="modal"><p class="eyebrow" id="endeyebrow">THE TRIAL ENDS</p><h2 class="title" id="endtitle">FALLEN</h2><p class="subtitle" id="endcopy"></p><button class="action" id="restart">RISE AGAIN</button><p class="footer-note">THE UNDERWORLD WILL REMEMBER.</p></section></div>
 <div class="touch-ui" id="touch"><div class="stick" id="stick"></div><div class="touch-actions"><button class="touch-btn dash" id="dashBtn">DASH</button><button class="touch-btn" id="attackBtn">ATTACK</button></div></div>
 </main>
 <script>
+(()=>{'use strict';
+const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d'),$=s=>document.querySelector(s),hud=$('#hud'),W=()=>innerWidth,H=()=>innerHeight;
+let dpr=1,cw=0,ch=0,arena={x:0,y:0,w:0,h:0},state='title',last=0,elapsed=0,shake=0,flash=0,room=1,kills=0,hp=100,maxHp=100,boonCount=0,weapon=null,attackHeld=false,attackCooldown=0,dashCooldown=0,dashTime=0,invuln=0,mouse={x:0,y:0},keys={},player={x:0,y:0,vx:0,vy:0,r:13,aim:0},enemies=[],shots=[],particles=[],embers=[],floats=[],drops=[],touchMove={x:0,y:0},touchOrigin=null;
+const weapons=[
+{id:'blade',name:'MOONBLADE',icon:'☽',desc:'A quick, sweeping arc of moonlit steel. Balanced reach and relentless rhythm.',stat:'CLOSE RANGE · SWEEP · FAST'},
+{id:'bow',name:'HEARTSEEKER',icon:'➶',desc:'A straight, piercing shot that rewards distance. Every arrow finds its mark.',stat:'LONG RANGE · PIERCE · PRECISE'},
+{id:'staff',name:'STARFALL STAFF',icon:'✧',desc:'Hurl a slow orb that bursts into a radiant blast. Own the space around you.',stat:'ARCANE · BLAST · CROWD CONTROL'}
+];
+const boons=[
+{icon:'✦',name:'Fury of Ares',desc:'Your attacks deal 30% more damage.',apply(){player.damage*=1.3}},
+{icon:'♡',name:'Ambrosia Veil',desc:'Restore 35 vitality and raise your max by 10.',apply(){maxHp+=10;hp=Math.min(maxHp,hp+35)}},
+{icon:'➤',name:'Swift Hermes',desc:'Move 15% faster and dash more often.',apply(){player.speed*=1.15;player.dashRate*=.78}},
+{icon:'◉',name:'Echoing Force',desc:'Your attacks strike 20% faster.',apply(){player.rate*=.8}},
+{icon:'⌁',name:'Golden Thread',desc:'Gain a shield: the next hit deals half damage.',apply(){player.shield=true}},
+{icon:'☼',name:'Vital Spark',desc:'Increase your maximum vitality by 25.',apply(){maxHp+=25;hp=Math.min(maxHp,hp+25)}}
+];
+function resize(){dpr=Math.min(devicePixelRatio||1,2);cw=canvas.width=Math.floor(W()*dpr);ch=canvas.height=Math.floor(H()*dpr);canvas.style.width=W()+'px';canvas.style.height=H()+'px';ctx.setTransform(dpr,0,0,dpr,0,0);let margin=Math.min(100,W()*.09),top=Math.max(100,H()*.17),bottom=Math.max(84,H()*.14);arena={x:margin,y:top,w:W()-margin*2,h:H()-top-bottom};if(player.x===0){player.x=W()/2;player.y=(arena.y+arena.y+arena.h)/2} }
+addEventListener('resize',resize);resize();
+function rng(a,b){return a+Math.random()*(b-a)}
+function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
+function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
+function say(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(say.timer);say.timer=setTimeout(()=>el.classList.remove('show'),1350)}
+function banner(text){const el=$('#banner');el.textContent=text;el.classList.add('show');clearTimeout(banner.timer);banner.timer=setTimeout(()=>el.classList.remove('show'),1700)}
+function startGame(id){weapon=weapons.find(w=>w.id===id);Object.assign(player,{x:W()/2,y:arena.y+arena.h*.68,vx:0,vy:0,r:13,speed:210,damage:id==='bow'?24:id==='staff'?32:27,rate:id==='bow'?.37:id==='staff'?.62:.31,dashRate:1.55,shield:false});hp=maxHp=100;kills=boonCount=0;room=1;enemies=[];shots=[];particles=[];drops=[];floats=[];$('#weaponname').textContent=weapon.name;$('#kills').textContent='0';$('#boons').textContent='0';$('#start').classList.add('hidden');$('#end').classList.add('hidden');$('#upgrade').classList.add('hidden');hud.style.display='block';$('#touch').classList.toggle('active',W()<740);state='playing';spawnRoom();updateHud()}
+$('#weaponChoices').innerHTML=weapons.map(w=>`<button class="weapon-card" data-id="${w.id}"><div class="icon">${w.icon}</div><h3>${w.name}</h3><p>${w.desc}</p><small>${w.stat}</small></button>`).join('');document.querySelectorAll('.weapon-card').forEach(b=>b.onclick=()=>startGame(b.dataset.id));
+function showEnd(won){state='end';hud.style.display='block';$('#touch').classList.remove('active');$('#endeyebrow').textContent=won?'THE GATES STAND OPEN':'THE TRIAL CLAIMS ANOTHER';$('#endtitle').innerHTML=won?'PASSAGE<br>WON':'FALLEN';$('#endcopy').textContent=won?`Three chambers silenced. ${kills} shades banished. The dark remembers your name.`:`You banished ${kills} shades before the underworld drew you in. The oath is not yet fulfilled.`;$('#end').classList.remove('hidden')}
+$('#restart').onclick=()=>{$('#start').classList.remove('hidden');$('#end').classList.add('hidden');hud.style.display='none';state='title'};
+function spawnRoom(){const amount=room===1?6:room===2?9:12;$('#roomlabel').textContent=`CHAMBER ${['I','II','III'][room-1]}`;$('#roomstatus').textContent=['THE SILENT COURT','HALL OF ASH','THE BLOOD GALLERY'][room-1];enemies=[];for(let i=0;i<amount;i++){let shooter=(room>1&&i%4===3)||(room===3&&i%3===2),elite=room===3&&i===0;let edge=Math.floor(Math.random()*4),x=edge===0?arena.x+24:edge===1?arena.x+arena.w-24:rng(arena.x+35,arena.x+arena.w-35),y=edge===2?arena.y+24:edge===3?arena.y+arena.h-24:rng(arena.y+35,arena.y+arena.h-35);enemies.push({x,y,vx:0,vy:0,r:elite?20:shooter?14:16,hp:(shooter?40:elite?125:58)*(1+(room-1)*.25),max:(shooter?40:elite?125:58)*(1+(room-1)*.25),speed:shooter?72:elite?63:86,damage:shooter?10:elite?18:13,kind:elite?'elite':shooter?'archer':'shade',cool:rng(.5,1.8),phase:rng(0,6),hit:0})}banner(`CHAMBER ${['I','II','III'][room-1]} — ${amount} SOULS`) }
+function updateHud(){$('#hptext').textContent=`${Math.ceil(hp)} / ${maxHp}`;$('#hpbar').style.width=`${clamp(hp/maxHp*100,0,100)}%`;$('#kills').textContent=kills;$('#boons').textContent=boonCount}
+function pickUpgrade(){state='upgrade';$('#touch').classList.remove('active');$('#upgrade').classList.remove('hidden');let picks=[...boons].sort(()=>Math.random()-.5).slice(0,3);$('#upgradeChoices').innerHTML=picks.map((b,i)=>`<button class="upgrade" data-pick="${i}"><div class="upicon">${b.icon}</div><h3>${b.name}</h3><p>${b.desc}</p></button>`).join('');document.querySelectorAll('.upgrade').forEach((el,i)=>el.onclick=()=>{picks[i].apply();boonCount++;room++;$('#boons').textContent=boonCount;$('#upgrade').classList.add('hidden');$('#touch').classList.toggle('active',W()<740);state='playing';player.x=W()/2;player.y=arena.y+arena.h*.65;spawnRoom();updateHud()})}

