function pickUpgrade(){state='upgrade';$('#touch').classList.remove('active');$('#upgrade').classList.remove('hidden');let picks=[...boons].sort(()=>Math.random()-.5).slice(0,3);$('#upgradeChoices').innerHTML=picks.map((b,i)=>`<button class="upgrade" data-pick="${i}"><div class="upicon">${b.icon}</div><h3>${b.name}</h3><p>${b.desc}</p></button>`).join('');document.querySelectorAll('.upgrade').forEach((el,i)=>el.onclick=()=>{picks[i].apply();boonCount++;room++;$('#boons').textContent=boonCount;$('#upgrade').classList.add('hidden');$('#touch').classList.toggle('active',W()<740);state='playing';player.x=W()/2;player.y=arena.y+arena.h*.65;spawnRoom();updateHud()})}
function drawArena(){let a=arena;ctx.save();ctx.shadowColor='#000';ctx.shadowBlur=40;ctx.fillStyle='#17131d';ctx.fillRect(a.x,a.y,a.w,a.h);ctx.restore();let grad=ctx.createRadialGradient(W()/2,a.y+a.h*.45,30,W()/2,a.y+a.h*.45,Math.max(a.w,a.h)*.75);grad.addColorStop(0,'#302431');grad.addColorStop(.58,'#26202a');grad.addColorStop(1,'#1c1721');ctx.fillStyle=grad;ctx.fillRect(a.x,a.y,a.w,a.h);
// worn flagstones
const tile=64;for(let x=Math.floor(a.x/tile)*tile;x<a.x+a.w;x+=tile)for(let y=Math.floor(a.y/tile)*tile;y<a.y+a.h;y+=tile){let gx=Math.floor(x/tile),gy=Math.floor(y/tile),v=(gx*17+gy*31)%5;ctx.fillStyle=`rgba(212,172,140,${.012+v*.003})`;ctx.fillRect(x+1,y+1,tile-2,tile-2);ctx.strokeStyle='rgba(220,190,160,.035)';ctx.lineWidth=1;ctx.strokeRect(x+.5,y+.5,tile-1,tile-1)}
// central sigil
let cx=a.x+a.w/2,cy=a.y+a.h/2;ctx.save();ctx.translate(cx,cy);ctx.rotate(elapsed*.025);ctx.strokeStyle='rgba(224,175,115,.14)';ctx.lineWidth=1;for(let r of [45,54,94,101]){ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.stroke()}for(let i=0;i<8;i++){ctx.rotate(Math.PI/4);ctx.beginPath();ctx.moveTo(48,0);ctx.lineTo(100,0);ctx.stroke();ctx.beginPath();ctx.moveTo(100,0);ctx.lineTo(91,-6);ctx.lineTo(91,6);ctx.closePath();ctx.stroke()}ctx.restore();
// boundary and corner stones
ctx.strokeStyle='#80604f';ctx.globalAlpha=.78;ctx.lineWidth=2;ctx.strokeRect(a.x,a.y,a.w,a.h);ctx.globalAlpha=.26;ctx.lineWidth=8;ctx.strokeRect(a.x+5,a.y+5,a.w-10,a.h-10);ctx.globalAlpha=1;
for(let i=0;i<4;i++){let px=i%2?a.x+a.w-25:a.x+25,py=i>1?a.y+a.h-25:a.y+25;ctx.fillStyle='#312633';ctx.beginPath();ctx.arc(px,py,12,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b28361';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#e3a873';ctx.globalAlpha=.72+.25*Math.sin(elapsed*3+i);ctx.beginPath();ctx.arc(px,py,3.5,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
// floating ember motes
for(let e of embers){e.y-=e.s*.22;e.x+=Math.sin(elapsed+e.phase)*.12;if(e.y<a.y)e.y=a.y+a.h;ctx.fillStyle=`rgba(226,157,98,${e.alpha})`;ctx.beginPath();ctx.arc(e.x,e.y,e.r,0,7);ctx.fill()}ctx.restore()}
function initEmbers(){embers=Array.from({length:75},()=>({x:rng(0,W()),y:rng(0,H()),r:rng(.4,1.8),s:rng(.2,1.4),phase:rng(0,7),alpha:rng(.12,.48)}))}
initEmbers();
function drawActor(x,y,r,color,glow,ang=0,kind='player',hit=0){ctx.save();ctx.translate(x,y);let bob=Math.sin(elapsed*5+x*.03)*1.3;ctx.translate(0,bob);ctx.fillStyle='#09070b77';ctx.beginPath();ctx.ellipse(0,r*.78,r*.95,r*.45,0,0,7);ctx.fill();ctx.shadowColor=glow;ctx.shadowBlur=hit?25:15;ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,0,r,0,7);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle=kind==='player'?'#ffdda0':'#edb08e';ctx.globalAlpha=.65;ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,r*.76,0,7);ctx.stroke();ctx.globalAlpha=1;
if(kind==='player'){ctx.rotate(ang);ctx.fillStyle='#f6d79d';ctx.beginPath();ctx.ellipse(r*.27,-r*.22,r*.25,r*.16,-.25,0,7);ctx.fill();ctx.strokeStyle='#f2d293';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-2,0);ctx.lineTo(r+10,0);ctx.stroke();ctx.strokeStyle='#fff0c7';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(r+4,-2);ctx.lineTo(r+12,0);ctx.lineTo(r+4,2);ctx.stroke();if(player.shield){ctx.strokeStyle='#f2ca75';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,r+6,0,7);ctx.stroke()}}
else{ctx.fillStyle='#100c16';ctx.beginPath();ctx.arc(-r*.25,-r*.12,2,0,7);ctx.arc(r*.25,-r*.12,2,0,7);ctx.fill();if(kind==='elite'){ctx.strokeStyle='#d5a25a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-8,-r+3);ctx.lineTo(-13,-r-8);ctx.lineTo(-3,-r+2);ctx.moveTo(8,-r+3);ctx.lineTo(13,-r-8);ctx.lineTo(3,-r+2);ctx.stroke()}}
ctx.restore()}

